const data = $input.first().json;
const weekNumber = $('Extract Week Number').first().json.weekNumber;
const events = data.events || [];

const games = [];

for (const event of events) {
  const gameId = event.id;
  const competition = event.competitions?.[0];

  if (!competition) continue;

  const homeTeam = competition.competitors.find(c => c.homeAway === 'home');
  const awayTeam = competition.competitors.find(c => c.homeAway === 'away');

  games.push({
    json: {
      gameId,
      weekNumber,
      homeTeam: homeTeam?.team?.abbreviation,
      homeTeamId: homeTeam?.team?.id,
      awayTeam: awayTeam?.team?.abbreviation,
      awayTeamId: awayTeam?.team?.id,
      gameDate: event.date,
      venue: competition.venue?.fullName
    }
  });
}

console.log(`🏈 Found ${games.length} games for Week ${weekNumber}`);

return games;

const games = $input.all();
const urls = [];

for (const game of games) {
  const g = game.json;

  // Home team roster URL
  urls.push({
    json: {
      url: `http://site.api.espn.com/apis/site/v2/sports/football/nfl/teams/${g.homeTeamId}/roster`,
      meta: {
        gameId: g.gameId,
        teamId: g.homeTeamId,
        teamAbbr: g.homeTeam,
        side: 'home'
      }
    }
  });

  // Away team roster URL
  urls.push({
    json: {
      url: `http://site.api.espn.com/apis/site/v2/sports/football/nfl/teams/${g.awayTeamId}/roster`,
      meta: {
        gameId: g.gameId,
        teamId: g.awayTeamId,
        teamAbbr: g.awayTeam,
        side: 'away'
      }
    }
  });
}

console.log(`📋 Built ${urls.length} roster URLs`);

return urls;

// Extract rosters WITH season stats (per team)
const rosterData = $input.item.json;

// Get team info
const teamInfo = rosterData.team || {};
const teamId = teamInfo.id;
const teamAbbr = teamInfo.abbreviation || 'UNK';

// Get metadata from Build Roster URLs node
const buildRosterItems = $('Build Roster URLs').all();
let meta = {};
for (const item of buildRosterItems) {
    if (item.json.meta?.teamId === teamId) {
        meta = item.json.meta;
        break;
    }
}

const gameId = meta.gameId;
const side = meta.side;

// Build injuries map
const injuries = {};
if (rosterData.team?.injuries) {
    for (const inj of rosterData.team.injuries) {
        const athleteId = inj.athlete?.id;
        if (athleteId) {
            injuries[athleteId] = {
                status: inj.status || 'Unknown',
                detail: inj.details?.fantasyStatus || inj.details?.type || ''
            };
        }
    }
}

// Extract players from offense position group
const players = [];
for (const positionGroup of (rosterData.athletes || [])) {
    if (positionGroup.position !== 'offense') continue;

    for (const athlete of (positionGroup.items || [])) {
        const position = athlete.position?.abbreviation || 'UNK';

        // Only include skill positions
        if (!['QB', 'RB', 'WR', 'TE', 'FB'].includes(position)) continue;

        const athleteId = athlete.id;
        const stats = athlete.stats || [];
        let seasonTDs = 0;
        let gamesPlayed = 1;
        let tdPerGame = 0;

        // Extract season stats
        for (const statGroup of stats) {
            if (statGroup.type === 'total' && statGroup.category === 'scoring') {
                for (const stat of (statGroup.stats || [])) {
                    if (stat.name === 'touchdowns') {
                        seasonTDs = parseFloat(stat.value) || 0;
                    }
                }
            }
            if (statGroup.type === 'total' && statGroup.category === 'general') {
                for (const stat of (statGroup.stats || [])) {
                    if (stat.name === 'gamesPlayed') {
                        gamesPlayed = Math.max(1, parseFloat(stat.value) || 1);
                    }
                }
            }
        }

        tdPerGame = gamesPlayed > 0 ? seasonTDs / gamesPlayed : 0;

        // Get depth chart order
        const depthChartOrder = athlete.depthChartOrder || 99;
        const isStarter = depthChartOrder === 1;
        const isBackup = depthChartOrder === 2;

        players.push({
            id: athleteId,
            name: athlete.displayName || athlete.fullName || 'Unknown',
            jersey: athlete.jersey || '',
            position,
            team: teamAbbr,
            teamId,
            gameId,
            side,
            headshot: athlete.headshot?.href || '',
            injury: injuries[athleteId] || null,
            injuryImpact: injuries[athleteId] ? 1 : 0,
            seasonTDs,
            gamesPlayed,
            tdPerGame,
            depthChartOrder,
            isStarter,
            isBackup
        });
    }
}

return {
    json: {
        gameId,
        team: teamAbbr,
        side,
        players,
        totalPlayers: players.length,
        starters: players.filter(p => p.isStarter).length
    }
};

// Parse Red Zone Rushing from Pro Football Reference HTML
const htmlData = $input.first().data;

console.log('🔍 Parsing red zone rushing HTML...');

// For now, return empty array since web scraping is complex
// In production, you'd use a proper HTML parser
const redZoneRushing = [];

console.log(`⚠️ Red zone rushing: Web scraping not implemented (would need HTML parser)`);
console.log(`   Returning empty array - predictions will use defaults`);

return {
    json: {
        redZoneRushing: redZoneRushing,
        source: 'Pro Football Reference',
        scrapedAt: new Date().toISOString(),
        note: 'Web scraping requires HTML parser - using defaults for now'
    }
};

// Parse Red Zone Receiving from Pro Football Reference HTML
const htmlData = $input.first().data;

console.log('🔍 Parsing red zone receiving HTML...');

// For now, return empty array since web scraping is complex
const redZoneReceiving = [];

console.log(`⚠️ Red zone receiving: Web scraping not implemented (would need HTML parser)`);
console.log(`   Returning empty array - predictions will use defaults`);

return {
    json: {
        redZoneReceiving: redZoneReceiving,
        source: 'Pro Football Reference',
        scrapedAt: new Date().toISOString(),
        note: 'Web scraping requires HTML parser - using defaults for now'
    }
};

// ===== NFL TD PREDICTION ALGORITHM V9 - TRULY POSITION NEUTRAL =====
let depthCharts = {};

try {
  const parseNode = $('Parse RapidAPI Data').first();
  if (parseNode?.json?.depthCharts) {
    depthCharts = parseNode.json.depthCharts;
    console.log(`\n✅ RapidAPI depth charts: ${Object.keys(depthCharts).length} players`);
  }
} catch (error) {
  console.log(`\n⚠️ RapidAPI data unavailable`);
}

const games = $input.all();
console.log(`\n📊 Processing ${games.length} games...\n`);

const starPlayers = {
  'Christian McCaffrey': { team: 'SF', bonus: 10 },
  'Tyreek Hill': { team: 'MIA', bonus: 10 },
  'CeeDee Lamb': { team: 'DAL', bonus: 10 },
  'Ja\'Marr Chase': { team: 'CIN', bonus: 10 },
  'Amon-Ra St. Brown': { team: 'DET', bonus: 10 },
  'A.J. Brown': { team: 'PHI', bonus: 10 },
  'Derrick Henry': { team: 'BAL', bonus: 10 },
  'Bijan Robinson': { team: 'ATL', bonus: 10 },
  'Jahmyr Gibbs': { team: 'DET', bonus: 10 },
  'Jonathan Taylor': { team: 'IND', bonus: 10 },
  'Josh Jacobs': { team: 'GB', bonus: 9 },
  'Saquon Barkley': { team: 'PHI', bonus: 9 },
  'Travis Kelce': { team: 'KC', bonus: 10 },
  'George Kittle': { team: 'SF', bonus: 10 },
  'Sam LaPorta': { team: 'DET', bonus: 9 }
};

const hasRapidAPI = Object.keys(depthCharts).length > 0;
const results = [];

for (const game of games) {
  const gameData = game.json;
  const gameId = gameData.gameId;
  const homeTeam = gameData.homeTeam;
  const awayTeam = gameData.awayTeam;
  const matchup = gameData.matchup || `${awayTeam} @ ${homeTeam}`;
  const vegasOdds = gameData.vegasOdds || {};
  const weather = gameData.weather || {};
  const defensive = gameData.defensive || {};

  console.log(`\n🏈 ${matchup}`);
  if (weather.condition) console.log(`  🌤️ Weather: ${weather.condition}, ${weather.temperature}°F, Wind ${weather.windSpeed}mph`);

  const players = gameData.players || [];

  if (players.length === 0) {
    console.log(`  ⚠️ No players found`);
    continue;
  }

  console.log(`  Found ${players.length} players`);

  const scoredPlayers = [];

  for (const player of players) {
    let tdScore = 0;
    const reasons = [];
    let depthOrder = 99;
    let depthPosition = '';

    // DEPTH CHART (up to 35 points - COMPLETELY NEUTRAL)
    if (hasRapidAPI) {
      const playerKey = `${player.id}_${player.team}`;
      const depthInfo = depthCharts[playerKey];

      if (depthInfo) {
        depthOrder = depthInfo.depthOrder || 99;
        depthPosition = depthInfo.depthPosition || '';

        if (depthOrder === 1) {
          // ALL STARTERS GET EXACT SAME POINTS
          tdScore += 35;
          reasons.push(`${player.position}1`);
        } else if (depthOrder === 2) {
          tdScore += 12;
          reasons.push('Backup');
        }
      }
    }

    // VEGAS ODDS (up to 30 points)
    const vegasKey = `${player.name}_${gameId}`;
    const vegasProb = vegasOdds[vegasKey];
    if (vegasProb) {
      const vegasScore = Math.round(vegasProb * 0.3);
      tdScore += vegasScore;
      reasons.push(`Vegas: ${vegasProb}%`);
    }

    // SEASON TD PERFORMANCE (up to 30 points)
    const tdPerGame = player.tdPerGame || 0;
    if (tdPerGame >= 0.8) {
      tdScore += 30;
      reasons.push(`${tdPerGame.toFixed(1)} TD/g`);
    } else if (tdPerGame >= 0.5) {
      tdScore += 20;
      reasons.push(`${tdPerGame.toFixed(1)} TD/g`);
    } else if (tdPerGame >= 0.3) {
      tdScore += 10;
      reasons.push(`${tdPerGame.toFixed(1)} TD/g`);
    }

    // POSITION BASE (REMOVED - NOW 0 POINTS)
    // Elite players will win based on performance, not position

    // 🛡️ DEFENSIVE MATCHUP (up to 15 points)
    if (defensive.homeVsDefense || defensive.awayVsDefense) {
      const isHome = player.team === homeTeam;
      const matchupDefense = isHome ? defensive.homeVsDefense : defensive.awayVsDefense;

      if (matchupDefense) {
        // Check position-specific matchup
        if (player.position === 'RB') {
          const runDefRank = matchupDefense.runDefenseRank || 16;
          if (runDefRank > 24) {
            tdScore += 15;
            reasons.push('Weak run D');
          } else if (runDefRank > 16) {
            tdScore += 8;
            reasons.push('Favorable run D');
          } else if (runDefRank < 8) {
            tdScore -= 10;
            reasons.push('Tough run D');
          }
        } else if (player.position === 'WR' || player.position === 'TE') {
          const passDefRank = matchupDefense.passDefenseRank || 16;
          if (passDefRank > 24) {
            tdScore += 15;
            reasons.push('Weak pass D');
          } else if (passDefRank > 16) {
            tdScore += 8;
            reasons.push('Favorable pass D');
          } else if (passDefRank < 8) {
            tdScore -= 10;
            reasons.push('Tough pass D');
          }
        }

        // Red zone defense matters for everyone
        const rzDefRank = matchupDefense.redZoneDefenseRank || 16;
        if (rzDefRank > 24) {
          tdScore += 5;
          reasons.push('Weak RZ D');
        }
      }
    }

    // 🔥 RECENT FORM (up to 15 points)
    if (player.recentForm) {
      const form = player.recentForm;
      if (form.isHot) {
        tdScore += 15;
        reasons.push(`Hot: ${form.last3GamesTDs} TDs in L3`);
      } else if (form.formScore >= 1) {
        tdScore += form.formScore * 5;
        reasons.push(`Recent: ${form.last3GamesTDs} TDs`);
      } else if (form.isCold) {
        tdScore -= 5;
        reasons.push('Cold streak');
      }
    }

    // 🌤️ WEATHER IMPACT (up to 5 points - MASSIVELY REDUCED BIAS)
    if (weather.highWind || weather.wetConditions || weather.coldWeather) {
      if (weather.highWind) {
        // Reduced from +8/-5 to +3/-3 (neutral impact)
        if (player.position === 'RB') {
          tdScore += 3;
          reasons.push('Wind slight edge');
        } else if (player.position === 'WR') {
          tdScore -= 3;
          reasons.push('Wind slight penalty');
        }
      }

      if (weather.wetConditions) {
        // Reduced from +6/-3 to +2/-1
        if (player.position === 'RB') {
          tdScore += 2;
          reasons.push('Wet slight edge');
        } else {
          tdScore -= 1;
        }
      }

      if (weather.coldWeather) {
        // Reduced from +4 to +1
        if (player.position === 'RB') {
          tdScore += 1;
          reasons.push('Cold minor edge');
        }
      }
    } else if (weather.isDome) {
      // Keep dome bonus for passing
      if (player.position === 'WR' || player.position === 'TE') {
        tdScore += 3;
        reasons.push('Dome game');
      }
    }

    // STAR PLAYER (up to 10 points)
    const starInfo = starPlayers[player.name];
    if (starInfo && starInfo.team === player.team) {
      tdScore += starInfo.bonus;
      reasons.push('Elite');
    }

    // INJURY PENALTY
    if (player.injury && player.injury.status !== 'Active') {
      tdScore -= 20;
      reasons.push(`⚠️ ${player.injury.status}`);
    }

    if (tdScore > 0) {
      scoredPlayers.push({
        name: player.name,
        playerId: player.id,
        team: player.team,
        position: player.position,
        headshot: player.headshot || '',
        injury: player.injury,
        tdScore: tdScore,
        scoringReasons: reasons,
        depthOrder: depthOrder,
        depthPosition: depthPosition,
        seasonTDs: player.seasonTDs || 0,
        tdPerGame: tdPerGame
      });
    }
  }

  scoredPlayers.sort((a, b) => b.tdScore - a.tdScore);

  console.log(`\n  Top 5 candidates:`);
  scoredPlayers.slice(0, 5).forEach((p, i) => {
    console.log(`    ${i + 1}. ${p.name} (${p.position}) - ${p.tdScore} pts: ${p.scoringReasons.join(', ')}`);
  });

  const winner = scoredPlayers[0];

  if (winner) {
    console.log(`\n  ✅ PREDICTION: ${winner.name} (${winner.position})`);

    // New max score: ~140 points (35+30+30+0+15+15+5+10-20)
    results.push({
      json: {
        gameId: gameId,
        matchup: matchup,
        homeTeam: homeTeam,
        awayTeam: awayTeam,
        playerName: winner.name,
        playerId: winner.playerId,
        team: winner.team,
        position: winner.position,
        tdProbabilityScore: winner.tdScore,
        confidence: Math.min(Math.round((winner.tdScore / 140) * 100), 95),
        headshot: winner.headshot,
        reasoning: winner.scoringReasons.join(' | '),
        injury: winner.injury || '',
        seasonTDs: winner.seasonTDs,
        tdPerGame: winner.tdPerGame.toFixed(2)
      }
    });
  }
}

console.log(`\n✅ Generated ${results.length} predictions with TRULY POSITION-NEUTRAL algorithm`);
console.log(`   Elite performers win regardless of position - NO position bias`);

if (results.length === 0) {
  throw new Error('No predictions generated - check game data');
}

return results;

// Pass through predictions WITH all original data preserved
const items = $input.all();

console.log(`📤 Select Top Scorer: Passing ${items.length} predictions to GPT-4 validation`);

// Just pass through - the predictions are already the top scorers per game
return items;

// FIXED: Extract predictions and properly merge with AI validation
const items = $input.all();
const results = [];

// Get week number from ESPN Scoreboard
let weekNumber = 10;
let seasonYear = 2025;
try {
    const weekData = $('Extract Week Number').first();
    weekNumber = weekData.json.weekNumber || 10;
    seasonYear = weekData.json.seasonYear || 2025;
} catch (e) {
    console.log('Could not get week/season, using defaults');
}

console.log(`\n📋 Preparing ${items.length} predictions for output...`);

// Get original predictions from Select Top Scorer (which has all the original data)
const originalPredictions = $('Select Top Scorer Per Game').all();

console.log(`  Original predictions: ${originalPredictions.length}`);
console.log(`  AI validations: ${items.length}`);

for (let i = 0; i < items.length; i++) {
    const aiResponse = items[i].json;

    // Get the corresponding original prediction (they should be in the same order)
    const originalPred = originalPredictions[i]?.json;

    if (!originalPred) {
        console.log(`⚠️ No original prediction found for index ${i}`);
        continue;
    }

    // Parse AI validation from OpenAI response
    let aiValidation = null;

    try {
        // OpenAI node returns response in different possible formats
        let content = null;

        if (aiResponse.message && aiResponse.message.content) {
            // Format 1: {message: {content: "..."}}
            content = aiResponse.message.content;
        } else if (aiResponse.content) {
            // Format 2: {content: "..."}
            content = aiResponse.content;
        } else if (aiResponse.text) {
            // Format 3: {text: "..."}
            content = aiResponse.text;
        } else if (typeof aiResponse === 'string') {
            // Format 4: Direct string
            content = aiResponse;
        }

        if (content) {
            // Remove markdown code blocks if present
            if (typeof content === 'string') {
                const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
                aiValidation = JSON.parse(cleaned);
            } else {
                aiValidation = content;
            }

            console.log(`  ✓ Parsed AI validation for ${originalPred.playerName}`);
        } else {
            console.log(`  ⚠️ Could not find AI response content for ${originalPred.playerName}`);
        }
    } catch (e) {
        console.log(`  ⚠️ Could not parse AI validation for ${originalPred.playerName}: ${e.message}`);
    }

    // Build final output with original prediction data + AI validation
    results.push({
        json: {
            // Original prediction fields
            week: weekNumber,
            seasonYear: seasonYear,
            weekNumber: weekNumber, // Alias for compatibility
            gameId: originalPred.gameId,
            matchup: originalPred.matchup,
            awayTeam: originalPred.awayTeam,
            homeTeam: originalPred.homeTeam,
            playerName: originalPred.playerName,
            playerId: originalPred.playerId,
            team: originalPred.team,
            position: originalPred.position,
            confidence: originalPred.confidence || originalPred.tdProbabilityScore || 50,
            headshot: originalPred.headshot || '',
            headshotURL: originalPred.headshot || '', // Alias for video generation
            reasoning: originalPred.reasoning || '',
            injury: originalPred.injury || '',
            seasonTDs: originalPred.seasonTDs || 0,
            tdPerGame: originalPred.tdPerGame || '0.00',

            // AI Validation (if successfully parsed)
            aiValidation: aiValidation ? {
                predictionAccuracy: aiValidation.predictionAccuracy || 'N/A',
                realTDProbability: aiValidation.realTDProbability || aiValidation.confidencePercentage || 'N/A',
                aiReasoning: aiValidation.reasoning || '',
                keyFactors: aiValidation.keyFactors || [],
                riskFactors: aiValidation.riskFactors || [],
                confidenceLevel: aiValidation.confidenceLevel || 'N/A',
                confidencePercentage: aiValidation.confidencePercentage || 'N/A',
                finalVerdict: aiValidation.finalVerdict || '',
                expertInsights: aiValidation.expertInsights || ''
            } : null
        }
    });
}

console.log(`✅ Prepared ${results.length} predictions for Week ${weekNumber}`);

if (results.length === 0) {
    throw new Error('No predictions to output - check previous nodes');
}

return results;

// Add team colors for video formatting
const teamColors = {
  'ARI':'#97233F','ATL':'#A71930','BAL':'#241773','BUF':'#00338D','CAR':'#0085CA',
  'CHI':'#0B162A','CIN':'#FB4F14','CLE':'#311D00','DAL':'#041E42','DEN':'#FB4F14',
  'DET':'#0076B6','GB':'#203731','HOU':'#03202F','IND':'#002C5F','JAX':'#006778',
  'KC':'#E31837','LAC':'#0080C6','LAR':'#003594','LV':'#000000','MIA':'#008E97',
  'MIN':'#4F2683','NE':'#002244','NO':'#D3BC8D','NYG':'#0B2265','NYJ':'#125740',
  'PHI':'#004C54','PIT':'#FFB612','SEA':'#002244','SF':'#AA0000','TB':'#D50A0A',
  'TEN':'#0C2340','WAS':'#5A1414'
};

// Get ALL items, not just the first one
const allItems = $input.all();

// Extract predictions from all items
const predictions = allItems.map(item => {
  const prediction = item.json;
  return {
    ...prediction,
    primaryColor: teamColors[prediction.team] || '#FFFFFF',
    headshotURL: prediction.headshot || prediction.headshotURL || ''
  };
});

// Get week number from first prediction
const weekNumber = predictions[0]?.weekNumber || predictions[0]?.week || 'Current';

console.log(`✅ Formatted ${predictions.length} predictions with team colors`);

return {
  json: {
    predictions: predictions,
    weekNumber: weekNumber,
    generatedAt: new Date().toISOString()
  }
