const d = $('Adapt Winner Predictions').first().json;
const preds = d.predictions || [];
if (!preds.length) throw new Error('No predictions for video');
const week = d.week;
const nextWeek = (week || 0) + 1;

const gcsObj = $input.first().json || {};
const fileId = gcsObj.id || '';
const voiceoverUrl = fileId
  ? `https://drive.google.com/uc?export=download&id=${fileId}`
  : '';
const voDur = gcsObj.size ? (Number(gcsObj.size) * 8) / 128000 : 68.0;
const MUSIC = 'https://storage.googleapis.com/bytesized-truths-audio-shorts/NFLsong.mp3';

const RECT = 'M 0 0 L 100 0 L 100 100 L 0 100 Z';
const CIRC = 'M 0 50 A 50 50 0 1 1 100 50 A 50 50 0 1 1 0 50 Z';
const isUp = p => p.tier === 'TOSS_UP' || p.tier === 'UPSET_PICK' || p.tier === 'UPSET';
const locks = preds.filter(p => p.tier === 'LOCK');
const upsets = preds.filter(isUp);
const strongs = preds.filter(p => p.tier !== 'LOCK' && !isUp(p));
const orderedGames = [...locks, ...strongs, ...upsets];

function countSyllables(word) {
  const w = String(word || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  if (!w) return 0;
  if (/^\d+$/.test(w)) return w.length * 1.6;
  const cleaned = w.replace(/(?:[^laeiouy]es|ed|[^laeiouy]e)$/, '').replace(/^y/, '');
  const m = cleaned.match(/[aeiouy]{1,2}/g);
  return m ? Math.max(1, m.length) : 1;
}

function speechWeight(text) {
  const str = String(text || '').trim();
  const words = str.split(/\s+/).filter(Boolean);
  const syllables = words.reduce((acc, w) => acc + countSyllables(w), 0);
  const commas = (str.match(/[,:]/g) || []).length;
  const stops = (str.match(/[.!?]/g) || []).length;
  return syllables * 0.19 + words.length * 0.08 + commas * 0.24 + stops * 0.42;
}

const introText = d.introVoLine || `Welcome to the Byte FYI Primetime Desk! Here are your NFL Week ${week} winner predictions, starting with our ${locks.length} Locks of the Week.`;
const outroText = d.outroVoLine || `Screenshot the Week ${week} lock board, drop the pick you are fading in the comments, and follow Byte FYI for Week ${nextWeek}!`;
const allTexts = [
  introText,
  ...orderedGames.map(p => p.voLine || `${p.pickName} over ${p.loseName} at ${p.winPct} percent.`),
  outroText
];
const allWeights = allTexts.map(speechWeight);
const totalWeight = allWeights.reduce((a, b) => a + b, 0) || 1;
const sceneDurations = allWeights.map((w, idx) => {
  const raw = (w / totalWeight) * voDur + (idx === allWeights.length - 1 ? 0.8 : 0.0);
  return Number(Math.max(2.2, raw).toFixed(2));
});

const els = [];
let t = 0.0;
let sceneCounter = 0;
const addScene = () => {
  const dur = sceneDurations[sceneCounter] || 4.0;
  sceneCounter += 1;
  const st = Number(t.toFixed(2));
  t = Number((t + dur).toFixed(2));
  return { st, dur };
};
const fade = [{ time: 0, duration: 0.28, type: 'fade' }];

function addScorebug(st, dur, rightBadgeText, rightBadgeColor, activeIdx, totalGames) {
