        continue;
    }

    if (!item.json.bookmakers || item.json.bookmakers.length === 0) {
        console.log(`⚠️ No odds for game ${item.json.gameId || item.json.id || 'unknown'}`);
        continue;
    }

    const bookmaker = item.json.bookmakers[0];
    if (!bookmaker.markets || bookmaker.markets.length === 0) {
        console.log(`⚠️ No markets for game ${item.json.id}`);
        continue;
    }

    const market = bookmaker.markets[0];
    const outcomes = market.outcomes || [];

    for (const outcome of outcomes) {
        const playerName = outcome.description;
        const americanOdds = outcome.price;

        // Convert American odds to implied probability
        let impliedProb;
        if (americanOdds > 0) {
            impliedProb = 100 / (americanOdds + 100);
        } else {
            impliedProb = Math.abs(americanOdds) / (Math.abs(americanOdds) + 100);
        }

        results.push({
            json: {
                gameId: item.json.id,
                playerName: playerName,
                americanOdds: americanOdds,
                vegasProb: Number((impliedProb * 100).toFixed(1)),
                bookmaker: bookmaker.title
            }
        });
    }
}

