const TIER = {LOCK:'#22C55E',STRONG:'#F59E0B',TOSS_UP:'#94A3B8',UPSET_PICK:'#A855F7',UPSET:'#A855F7'};
const TC = {ARI:'#97233F',ATL:'#A71930',BAL:'#241773',BUF:'#00338D',CAR:'#0085CA',CHI:'#C83803',CIN:'#FB4F14',CLE:'#FF3C00',DAL:'#003594',DEN:'#FB4F14',DET:'#0076B6',GB:'#FFB612',HOU:'#A71930',IND:'#1D63B4',JAX:'#00A3A3',KC:'#E31837',LV:'#A5ACAF',LAC:'#0080C6',LAR:'#FFA300',MIA:'#008E97',MIN:'#4F2683',NE:'#C60C30',NO:'#D3BC8D',NYG:'#A71930',NYJ:'#2E8B57',PHI:'#006D62',PIT:'#FFB612',SF:'#AA0000',SEA:'#69BE28',TB:'#D50A0A',TEN:'#4B92DB',WSH:'#FFB612',WAS:'#FFB612'};
const SPOKEN_TEAM = {
  ARI:'Arizona Cardinals', ATL:'Atlanta Falcons', BAL:'Baltimore Ravens', BUF:'Buffalo Bills',
  CAR:'Carolina Panthers', CHI:'Chicago Bears', CIN:'Cincinnati Bengals', CLE:'Cleveland Browns',
  DAL:'Dallas Cowboys', DEN:'Denver Broncos', DET:'Detroit Lions', GB:'Green Bay Packers',
  HOU:'Houston Texans', IND:'Indianapolis Colts', JAX:'Jacksonville Jaguars', KC:'Kansas City Chiefs',
  LV:'Las Vegas Raiders', LAC:'Los Angeles Chargers', LAR:'Los Angeles Rams', MIA:'Miami Dolphins',
  MIN:'Minnesota Vikings', NE:'New England Patriots', NO:'New Orleans Saints', NYG:'New York Giants',
  NYJ:'New York Jets', PHI:'Philadelphia Eagles', PIT:'Pittsburgh Steelers', SF:'San Francisco Forty-Niners',
  SEA:'Seattle Seahawks', TB:'Tampa Bay Buccaneers', TEN:'Tennessee Titans', WSH:'Washington Commanders',
  WAS:'Washington Commanders'
};
const spokenSpread = s => {
  const m = String(s || '').match(/([+-]?\d+(?:\.\d+)?)/);
  if (!m) return '';
  const num = Math.abs(parseFloat(m[1]));
  if (!num) return 'even money';
  const whole = Math.floor(num);
  const half = Math.abs(num - whole - 0.5) < 0.1;
  return half ? `favored by ${whole} and a half` : `favored by ${whole}`;
};
const hx = h => { h = h.replace('#',''); return [0,2,4].map(i => parseInt(h.substr(i,2),16)); };
const lum = c => (0.2126*c[0] + 0.7152*c[1] + 0.0722*c[2]) / 255;
const lighten = (c,f) => '#' + c.map(x => Math.round(x + (255-x)*f).toString(16).padStart(2,'0')).join('');
const colorOf = ab => { const base = TC[ab] || '#64748B'; const rgb = hx(base); const L = lum(rgb); return { base, accent: L < 0.25 ? lighten(rgb, 0.35) : base, text: L > 0.6 ? '#0B1220' : '#FFFFFF' }; };
const logo = a => `https://a.espncdn.com/i/teamlogos/nfl/500/${String(a).toLowerCase()}.png`;

function cleanSegment(s) {
  return String(s || '')
    .replace(/→/g, '->')
    .replace(/\s*—\s*film[^·]*/gi, '')
    .replace(/\s*\([+-]?[\d.]+(?:%|pp)\s*(?:adj|home|away)?\)/gi, '')
    .trim();
}

function cleanTrunc(s, maxLen = 98) {
  s = String(s || '').trim();
  if (s.length <= maxLen) return s;
  if (s.includes('  •  ')) {
    const first = s.split('  •  ')[0];
    if (first.length <= maxLen) return first;
  }
  const cut = s.slice(0, maxLen);
  const lastSpace = cut.lastIndexOf(' ');
  return (lastSpace > 40 ? cut.slice(0, lastSpace) : cut).replace(/[•,\-:]+$/, '').trim();
}

function parseWhy(whyStr, spread, ou) {
  const parts = String(whyStr || '').split('·').map(p => p.trim()).filter(Boolean);
  const marketParts = [], sharpParts = [], tapeParts = [];
  parts.forEach((pt, idx) => {
    let cleaned = pt;
    if (idx === 0 && cleaned.includes('—')) {
      cleaned = cleaned.split('—').slice(1).join('—').trim();
    }
    cleaned = cleanSegment(cleaned);
    const low = cleaned.toLowerCase();
    if (low.includes('sharp') || low.includes('steamed') || low.includes('injur') || low.includes('cluster') || low.includes('rest') || low.includes('situational')) {
      sharpParts.push(cleaned);
    } else if (low.includes('vegas') || low.includes('kalshi') || low.includes('polymarket') || low.includes('de-vigged')) {
      marketParts.push(cleaned);
    } else if (low.includes('tape') || low.includes('expert') || low.includes('video')) {
      tapeParts.push(cleaned);
    } else {
      sharpParts.push(cleaned);
    }
  });
  const mLine = marketParts.length ? marketParts.slice(0, 2).join('  •  ') : `Vegas Spread: ${spread || 'Pick'}  •  O/U ${ou || '44.5'}`;
  const sLine = sharpParts.length ? sharpParts.slice(0, 1).join('  •  ') : 'Composite Power Rating & Situational Rest Edge';
  const tLine = tapeParts.length ? tapeParts.slice(0, 2).join('  •  ') : 'Film Room & Expert Consensus Aligned on Favorite';
  return {
    marketLine: cleanTrunc(mLine, 98),
    sharpLine: cleanTrunc(sLine, 98),
    tapeLine: cleanTrunc(tLine, 98),
  };
}

const predictions = games.map(g => {
